 if(d.confirmException){action='handoverException';id=d.confirmException;payload={receiver:document.getElementById('exception-receiver').value,reason:document.getElementById('exception-reason').value,confirmationMethod:document.getElementById('exception-method').value,customerConfirmed:document.getElementById('exception-confirmed').checked};}
